@st.cache_data(show_spinner="Loading processed data...")
def load_data() -> dict[str, pd.DataFrame]:
    if not (PROCESSED / "sales.parquet").exists():
        data_pipeline.run()
    return A.load_all()


@st.cache_data(show_spinner="Computing analytics (first load only)...")
def load_results() -> dict:
    import run_pipeline as RP

    return RP.build_results(load_data())


def plot(fig: go.Figure, height: int = 380) -> None:
    fig.update_layout(
        height=height, margin=dict(l=10, r=10, t=44, b=10), template="plotly_dark", legend_title_text="",
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(2,11,20,0.35)",
        font=dict(family=FONT, color=TXT2, size=12), title_font=dict(family=FONT, color=TXT, size=15),
        legend=dict(font=dict(color=TXT2), bgcolor="rgba(0,0,0,0)"),
        colorway=CHART_COLORWAY,
        hoverlabel=dict(bgcolor=PANEL2, bordercolor=SKY, font=dict(color=TXT)),
    )
    fig.update_xaxes(gridcolor=GRID, linecolor="rgba(25,191,255,0.30)", zerolinecolor=GRID, tickfont=dict(color=MUTED), title_font=dict(color=MUTED))
    fig.update_yaxes(gridcolor=GRID, linecolor="rgba(25,191,255,0.30)", zerolinecolor=GRID, tickfont=dict(color=MUTED), title_font=dict(color=MUTED))
    for ax in fig.select_yaxes():
        if getattr(ax, "overlaying", None):
            ax.update(showgrid=False)
    st.plotly_chart(fig, width="stretch")


def kpi_row(items: list[tuple[str, str, str | None]]) -> None:
    for col, (label, value, delta) in zip(st.columns(len(items)), items):
        col.metric(label, value, delta)


def callout(kind: str, text: str) -> None:
    body = re.sub(r"\*\*(.+?)\*\*", r"<b>\1</b>", _html.escape(text, quote=False))
    st.markdown(f'<div class="hv-callout {kind}">{body}</div>', unsafe_allow_html=True)


def insight_card(title: str, text: str) -> None:
    st.markdown(f'<div class="hv-card"><h5>{_html.escape(title)}</h5><p>{_html.escape(text, quote=False)}</p></div>', unsafe_allow_html=True)


# ------------------------------------------------------------------- pages
def page_overview(d, R, s):
    st.header("Executive Overview")
    fy = A.kpi_by_period(s)
    cur, prev = fy.iloc[-1], fy.iloc[-2] if len(fy) > 1 else None
    delta = lambda col: f"{cur[col] / prev[col] - 1:+.1%} vs prior FY" if prev is not None else None
    kpi_row([
        ("Net sales (latest FY)", fmt_egp(cur.Net_Sales), delta("Net_Sales")),
        ("Gross profit", fmt_egp(cur.Gross_Profit), delta("Gross_Profit")),
        ("Gross margin", fmt_pct(cur.Gross_Margin), f"{(cur.Gross_Margin - prev.Gross_Margin) * 100:+.1f} pts" if prev is not None else None),
        ("Units", f"{cur.Units:,.0f}", delta("Units")),
        ("Avg discount", fmt_pct(cur.Avg_Discount), None),
    ])
    mt = A.monthly_trend(s)
    fig = go.Figure()
    fig.add_bar(x=mt.Month, y=mt.Net_Sales, name="Net sales", marker_color=NAVY)
    fig.add_scatter(x=mt.Month, y=mt.Gross_Margin, name="Gross margin", yaxis="y2", line=dict(color=AMBER, width=3))
    fig.update_layout(yaxis2=dict(overlaying="y", side="right", tickformat=".0%", range=[0.08, 0.22]), title="Monthly net sales and gross margin")
    plot(fig)

    st.subheader("What is happening? Why? What needs attention? What should management do?")
    m = st.columns(4)
    with m[0]:
        insight_card("WHAT IS HAPPENING", "Sales grew 10.8% in FY25 but only 3.3% in FY26; margin is flat at ~15.5%. Online +60% in two years, wholesale +13%, retail -5%.")
    with m[1]:
        insight_card("WHY", "Wholesale is 85% of sales but earns 11.9% margin: discounts average 32.6%, chosen with no link to order size. Retail/online earn 35-37%.")
    with m[2]:
        insight_card("NEEDS ATTENTION", "4,876 loss-making wholesale invoices; EGP 7.5M of excess retail/online stock vs wholesale at 11 days of cover; 2 suppliers collapsed to ~15% on-time; cost of poor quality = 31% of gross profit.")
    with m[3]:
        insight_card("WHAT TO DO", "Install a wholesale deal desk (tiered cap + margin floor): +EGP 2.9-4.9M GP/yr. Rebalance stock, fix SUP04/SUP09, target Sewing/Finishing, win back 3,745 at-risk customers.")
    st.subheader("Value at stake per year (gross profit)")
    va = R["value_at_stake"]
    f = px.bar(va.sort_values("Base"), x="Base", y="Action", orientation="h", error_x=va.sort_values("Base").High - va.sort_values("Base").Base, error_x_minus=va.sort_values("Base").Base - va.sort_values("Base").Low, color_discrete_sequence=[GREEN])
    f.update_layout(xaxis_title="EGP per year (bar = base, whisker = low-high)", yaxis_title="")
    plot(f, 380)


def page_sales_customers(d, R, s):
    st.header("Sales & Customers")
    t1, t2, t3 = st.tabs(["Channels & products", "Discounts", "Customers"])
    with t1:
        sc = A.channel_scorecard(s)
        c1, c2 = st.columns(2)
        with c1:
            f = go.Figure()
            f.add_bar(x=sc.Channel, y=sc.Net_Share, name="Share of net sales", marker_color=NAVY)
            f.add_bar(x=sc.Channel, y=sc.GP_Share, name="Share of gross profit", marker_color=TEAL)
            f.update_layout(barmode="group", yaxis_tickformat=".0%", title="Revenue share vs profit share")
            plot(f)
        with c2:
            g = A.channel_growth(s)
            plot(px.line(g, x="Fiscal_Year", y="Net_Sales", color="Channel", markers=True, color_discrete_map=CHANNEL_COLORS, title="Net sales by channel and fiscal year"))
        st.dataframe(sc[["Channel", "Net_Sales", "Gross_Profit", "Gross_Margin", "GP_per_Unit", "AOV", "Units_per_Invoice", "Refund_Rate", "Return_Rate_Lines"]].style.format(
            {"Net_Sales": "{:,.0f}", "Gross_Profit": "{:,.0f}", "Gross_Margin": "{:.1%}", "GP_per_Unit": "{:,.1f}", "AOV": "{:,.0f}", "Units_per_Invoice": "{:.1f}", "Refund_Rate": "{:.1%}", "Return_Rate_Lines": "{:.1%}"}), width="stretch", hide_index=True)
        pc = A.product_contribution(s)
        fam = st.multiselect("Product family", sorted(pc.Product_Family.unique()), default=sorted(pc.Product_Family.unique()))
        top = pc[pc.Product_Family.isin(fam)].head(15)
        plot(px.bar(top, x="Gross_Profit", y="Product_Name", orientation="h", color="Gross_Margin", color_continuous_scale="Viridis", title="Top products by gross profit (colour = margin)").update_yaxes(autorange="reversed"), 460)
        geo = A.geo_demand(s)
        plot(px.bar(geo.groupby(["Customer_Governorate", "Channel"], as_index=False).Net_Sales.sum().sort_values("Net_Sales", ascending=False).head(30), x="Net_Sales", y="Customer_Governorate", color="Channel", orientation="h", color_discrete_map=CHANNEL_COLORS, title="Geographic demand").update_yaxes(categoryorder="total ascending"), 420)
    with t2:
        di = A.discount_impact(s)
        plot(px.line(di, x="Discount_Band", y="Gross_Margin", color="Channel", markers=True, color_discrete_map=CHANNEL_COLORS, title="Gross margin by discount band").update_yaxes(tickformat=".0%"))
        st.dataframe(A.discount_leakage(s), width="stretch", hide_index=True)
        st.caption("Promotion test: Jun-Jul retail/online volume lift vs May/Aug, by year")
        st.dataframe(R["promo_test"].style.format("{:.3f}"), width="stretch", hide_index=True)
        callout("warn", "The Jun-Jul 2026 promo raised discounts from 7.3% to 9.7% but volume lift (+5.2%) matched the no-promo years (+5.7%, +5.9%): the extra discount bought nothing.")
    with t3:
        seg = R["rfm_segments"]
        c1, c2 = st.columns(2)
        with c1:
            f = go.Figure()
            f.add_bar(y=seg.Segment, x=seg.Customer_Share, orientation="h", name="Share of customers", marker_color=GREY)
            f.add_bar(y=seg.Segment, x=seg.Sales_Share, orientation="h", name="Share of sales", marker_color=NAVY)
            f.update_layout(barmode="group", xaxis_tickformat=".0%", title="RFM segments (retail customers)")
            plot(f, 430)
        with c2:
            ret = R["cohorts"].drop(columns="Cohort_Size")
            ret.index = ret.index.astype(str)
            plot(px.imshow(ret, text_auto=".0%", color_continuous_scale="Viridis", aspect="auto", title="Cohort retention by quarter since first order"), 430)
        st.dataframe(seg[["Segment", "Customers", "Net_Sales", "Avg_Orders", "AOV", "Median_Recency", "Opted_In"]].style.format({"Net_Sales": "{:,.0f}", "Avg_Orders": "{:.1f}", "AOV": "{:,.0f}", "Median_Recency": "{:.0f}", "Opted_In": "{:.0%}"}), width="stretch", hide_index=True)
        callout("bad", "3,745 'At Risk (high frequency)' customers are 16% of the base and 32% of sales, silent for a median 229 days; 65% are opted-in for WhatsApp/SMS win-back.")


def page_operations(d, R, s):
    st.header("Operations & Inventory")
    t1, t2, t3, t4 = st.tabs(["Inventory & replenishment", "Production", "Quality", "Printing & downtime"])
    with t1:
        diag = R["inventory_diag"]
        loc = R["inventory_location"]
        kpi_row([
            ("Stock value", fmt_egp(loc.Stock_Value.sum()), None), ("Excess stock value", fmt_egp(loc.Excess_Value.sum()), f"{loc.Excess_Value.sum() / loc.Stock_Value.sum():.0%} of stock"),
            ("Wholesale cover (median)", f"{loc.set_index('Location_Name').loc['El-Sharnouby Wholesale Desk', 'Median_Cover_Days']:.0f} days", None),
            ("Wholesale SKUs below ROP/out", str(int(loc.set_index('Location_Name').loc['El-Sharnouby Wholesale Desk', 'Below_ROP_or_Stockout'])), "of 59"),
        ])
        c1, c2 = st.columns(2)
        with c1:
            plot(px.box(diag.assign(Days_of_Cover=diag.Days_of_Cover.clip(upper=400)), x="Location_Name", y="Days_of_Cover", color="Location_Name", title="Days of cover per SKU (capped at 400)").update_layout(showlegend=False))
        with c2:
            st.dataframe(diag.groupby(["Location_Name", "Status"]).size().unstack(fill_value=0), width="stretch")
            hist = R["history"].groupby("Month").Units.sum().reset_index()
            fc = R["forecast_12m"].groupby("Month").Units_Forecast.sum().reset_index()
            f = go.Figure()
            f.add_scatter(x=hist.Month, y=hist.Units, name="Actual", line=dict(color=NAVY))
            f.add_scatter(x=fc.Month, y=fc.Units_Forecast, name="Forecast", line=dict(color=AMBER, dash="dash"))
            f.update_layout(title=f"Demand forecast (backtest WAPE {R['backtest_metrics'].set_index('Method').loc['si_growth', 'WAPE']:.0%} at SKU x location)")
            plot(f, 300)
        st.subheader("Replenishment plan (30/60/90-day forecast driven)")
        plan = R["replenishment"]
        loc_pick = st.selectbox("Location", ["All"] + sorted(plan.Location_Name.unique()))
        act_pick = st.multiselect("Action", sorted(plan.Action.unique()), default=["Order now (urgent)", "Order"])
        view = plan[plan.Action.isin(act_pick) & ((plan.Location_Name == loc_pick) | (loc_pick == "All"))]
        fh = R["forecast_horizons"]
        view = view.merge(fh[["Location_ID", "Product_ID", "Forecast_30D", "Forecast_60D", "Forecast_90D"]], on=["Location_ID", "Product_ID"], how="left")
        st.dataframe(view[["Location_Name", "Product_Name", "Closing_Stock", "Forecast_30D", "Forecast_60D", "Forecast_90D", "Model_Reorder_Point", "Suggested_Order_Qty", "Order_Value_EGP", "Surplus_Units", "Action"]].sort_values("Order_Value_EGP", ascending=False).style.format(
            {"Closing_Stock": "{:,.0f}", "Forecast_30D": "{:,.0f}", "Forecast_60D": "{:,.0f}", "Forecast_90D": "{:,.0f}", "Model_Reorder_Point": "{:,.0f}", "Suggested_Order_Qty": "{:,.0f}", "Order_Value_EGP": "{:,.0f}", "Surplus_Units": "{:,.0f}"}), width="stretch", hide_index=True, height=360)
        st.caption("Transfer suggestions (same SKU, surplus location -> deficit location)")
        st.dataframe(R["rebalancing"].head(15), width="stretch", hide_index=True)
    with t2:
        lines = R["line_scorecard"].merge(R["line_significance"][["Line_ID", "p_value"]], on="Line_ID")
        c1, c2 = st.columns(2)
        with c1:
            plot(px.bar(lines, x="Line_ID", y="Delayed_Share", color="p_value", color_continuous_scale="RdBu", title="Share of orders delayed (colour = p-value vs other lines)").update_yaxes(tickformat=".0%"))
        with c2:
            bn = R["bottleneck"]
            plot(px.bar(bn, x="Primary_Bottleneck", y="Delay_Days", title="Delay days by bottleneck stage", color_discrete_sequence=[ORANGE]))
        c3, c4 = st.columns(2)
        with c3:
            plot(px.bar(R["overtime"], x="OT_Band", y="Delayed_Share", title="Delay rate by overtime hours per order", color_discrete_sequence=[RED]).update_yaxes(tickformat=".0%"))
        with c4:
            pm = R["production_monthly"]
            plot(px.line(pm, x="Month", y=["Capacity_Util_Reported"], color_discrete_sequence=[TEAL], title="Capacity utilisation (hub-reported garments / 5,000 per day x 26 days)").update_yaxes(tickformat=".0%"))
        st.dataframe(lines.drop(columns=["p_value"]).style.format({"Plan_Attainment": "{:.1%}", "Reject_Rate": "{:.1%}", "Delayed_Share": "{:.1%}", "Efficiency": "{:.1f}", "Avg_Delay_Days": "{:.2f}"}), width="stretch", hide_index=True)
    with t3:
        c1, c2 = st.columns(2)
        with c1:
            plot(px.bar(R["defect_pareto"], x="Defect_Type", y="Loss_EGP", title="Quality loss by defect type", color_discrete_sequence=[RED]))
        with c2:
            copq = R["copq"]
            plot(px.bar(copq, x="EGP", y="Component", orientation="h", color="Type", title=f"Cost of poor quality: {fmt_egp(copq.EGP.sum())} ({copq.Pct_of_Gross_Profit.sum():.0%} of gross profit)"))
        st.dataframe(R["quality_return_link"], width="stretch", hide_index=True)
        st.dataframe(R["product_quality_priority"], width="stretch", hide_index=True)
    with t4:
        ms = R["machines"]
        c1, c2 = st.columns(2)
        with c1:
            plot(px.bar(ms, x="Machine_ID", y="Reject_Rate", title="Reject rate by printer", color_discrete_sequence=[AMBER]).update_yaxes(tickformat=".1%"))
        with c2:
            plot(px.bar(ms, x="Machine_ID", y="Downtime_Hours", color="Unplanned_Share", color_continuous_scale="YlOrRd", title="Downtime hours (colour = unplanned share)"))
        plot(px.bar(R["downtime_reasons"], x="Hours", y="Reason", color="Planned", orientation="h", title="Downtime hours by reason (all areas)"), 300)
        st.dataframe(ms[["Machine_ID", "Yield", "Reject_Rate", "Reprint_Rate", "Cost_per_Good_Unit", "Downtime_Hours", "Unplanned_Share", "Priority_Score"]].style.format({"Yield": "{:.1%}", "Reject_Rate": "{:.2%}", "Reprint_Rate": "{:.2%}", "Cost_per_Good_Unit": "{:.2f}", "Downtime_Hours": "{:,.0f}", "Unplanned_Share": "{:.0%}", "Priority_Score": "{:.2f}"}), width="stretch", hide_index=True)


def page_marketing(d, R, s):
    st.header("Marketing")
    mp = R["marketing_platform"]
    att = R["attribution"]
    kpi_row([("Spend", fmt_egp(mp.Spend.sum()), None), ("Reported ROAS", f"{mp.Revenue.sum() / mp.Spend.sum():.1f}x", None), ("Break-even ROAS (gross profit)", f"{R['breakeven_roas']:.1f}x", None), ("Attribution vs actual online sales", f"{att['overclaim_vs_online']:.1f}x", "over-claimed")])
    c1, c2 = st.columns(2)
    with c1:
        f = go.Figure()
        f.add_bar(x=mp.Platform, y=mp.Spend_Share, name="Share of spend", marker_color=GREY)
        f.add_bar(x=mp.Platform, y=mp.Revenue_Share, name="Share of attributed revenue", marker_color=TEAL)
        f.update_layout(barmode="group", yaxis_tickformat=".0%", title="Budget vs return by platform")
        plot(f)
    with c2:
        mc = R["marketing_campaigns"]
        plot(px.scatter(mc, x="Spend_EGP", y="ROAS", color="Platform", log_y=True, hover_data=["Campaign_ID", "Product_ID", "Outlier"], title="Campaigns: spend vs ROAS (log)"))
    st.dataframe(mp[["Platform", "Campaigns", "Spend", "Revenue", "ROAS", "CAC", "CTR", "CVR"]].style.format({"Spend": "{:,.0f}", "Revenue": "{:,.0f}", "ROAS": "{:.2f}", "CAC": "{:.1f}", "CTR": "{:.2%}", "CVR": "{:.2%}"}), width="stretch", hide_index=True)
    t1, t2 = st.tabs(["Product x platform", "Web funnel"])
    with t1:
        mf = R["marketing_product_family"]
        plot(px.density_heatmap(mf, x="Platform", y="Product_Family", z="ROAS", text_auto=".1f", histfunc="avg", color_continuous_scale="Viridis", title="ROAS by platform and product family"), 320)
        st.dataframe(R["marketing_campaigns"].query("Outlier != 'Normal'")[["Campaign_ID", "Platform", "Product_ID", "Spend_EGP", "ROAS", "Outlier"]].sort_values("ROAS"), width="stretch", hide_index=True)
    with t2:
        wf, lt = R["web_funnel"], R["load_time"]
        c1, c2 = st.columns(2)
        with c1:
            plot(px.line(wf, x="Month", y="Conversion", color_discrete_sequence=[TEAL], title="Web conversion").update_yaxes(tickformat=".1%"), 320)
        with c2:
            plot(px.bar(lt, x="Load_Band", y="Conversion", color_discrete_sequence=[NAVY], title="Conversion by page-load time").update_yaxes(tickformat=".1%"), 320)
    st.subheader("Budget reallocation scenario")
    share = st.slider("Share of Influencer spend moved to Google", 0, 100, 50, 10) / 100
    eff = st.slider("Google marginal efficiency (share of average ROAS)", 10, 100, 50, 10) / 100
    recon = st.checkbox("Reconcile revenue to actual sales (recommended)", value=True)
    r = A.reallocation_scenario(mp, marginal_efficiency=eff, haircut=att["haircut_factor_non_wholesale"] if recon else 1.0, donor_shares={"Influencer": share, "Meta": 0.15, "TikTok": 0.15})
    kpi_row([("Budget moved", fmt_egp(r["budget_shifted"]), None), ("Net revenue change", fmt_egp(r["net_revenue_reconciled"]), None), ("Net gross profit change (3 yrs)", fmt_egp(r["net_gross_profit"]), None)])
    callout("info", "Platform-attributed revenue is 5.5x actual online sales: rankings are reliable, absolute ROAS is not. Validate with holdout tests before scaling.")


def page_procurement(d, R, s):
    st.header("Procurement & Suppliers")
    po = d["procurement"]
    kpi_row([("PO spend", fmt_egp(po.Spend_EGP.sum()), None), ("On-time delivery", fmt_pct(po.On_Time.mean()), None), ("OTIF", fmt_pct(po.OTIF.mean()), None), ("Avg lead time", f"{po.Lead_Time_Days.mean():.1f} days", None)])
    tr = R["supplier_trend"].reset_index().melt(id_vars="Period", var_name="Supplier", value_name="OTD")
    tr["Group"] = tr.Supplier.where(tr.Supplier.isin(PROBLEM_SUPPLIERS), "Other suppliers")
    f = px.line(tr, x="Period", y="OTD", color="Supplier", color_discrete_sequence=[GREY] * 12, title="Quarterly on-time delivery by supplier")
    for trace in f.data:
        hot = trace.name in PROBLEM_SUPPLIERS
        trace.update(line=dict(color=RED if hot else GREY, width=4 if hot else 1), opacity=1 if hot else 0.6)
    f.update_yaxes(tickformat=".0%")
    plot(f, 380)
    am = R["supplier_actions"]
    st.dataframe(am.style.format({"OTD": "{:.0%}", "Avg_Days_Late": "{:.1f}", "Spend": "{:,.0f}", "Spend_Share": "{:.1%}"}), width="stretch", hide_index=True)
    mat = R["materials"]
    plot(px.scatter(mat, x="Shortage_Risk", y="Spend", size="Products_Using", color="Material_Category", hover_name="Material_Name", title="Material shortage risk vs spend (bubble = products using the material)"), 380)
    st.dataframe(mat[["Material_Name", "Spend", "OTD", "Lead_Time", "Standard_Lead_Time", "Price_Change_FY24_to_FY26", "Products_Using", "Coverage_vs_BOM", "Criticality", "Shortage_Risk"]].style.format(
        {"Spend": "{:,.0f}", "OTD": "{:.0%}", "Lead_Time": "{:.1f}", "Price_Change_FY24_to_FY26": "{:+.1%}", "Coverage_vs_BOM": "{:.2f}", "Criticality": "{:.2f}", "Shortage_Risk": "{:.2f}"}), width="stretch", hide_index=True)
    callout("bad", "SUP04 and SUP09 fell from ~65% to ~15% on-time in 2025 and carry 16% of PO spend. Statistically this has not (yet) caused production delays (r=0.05) - fix it before it does.")


def page_cases(d, R, s):
    st.header("Case Briefs")
    cases = pd.read_csv(ROOT / "data" / "raw" / "Case_Briefs.csv", encoding="utf-8-sig")
    answers = {
        1: "Growth is not converting: sales +14.5% in two years, margin flat ~15.5%; wholesale (85% of sales) earns 11.9%. Action: manage on gross profit; govern wholesale discounts.",
        2: "Retail repeat 83.5%; 3,745 at-risk high-frequency customers hold 32% of sales; next-quarter retention of new cohorts fell 91% -> ~44%. Action: win-back + onboarding.",
        3: "Online +60%, wholesale +13%, retail -5%; online returns 2x retail (size/fit). Action: fix size guidance, investigate retail decline, price wholesale to contribution.",
        4: "Wholesale 11 days cover (36/59 SKUs below ROP) vs 4 months in retail/online (EGP 7.5M excess). Forecast WAPE 23% (vs 54% naive). Action: forecast-driven replenishment.",
        5: "ROAS CRM 67x, Google 10x, TikTok 4.9x, Meta 4.4x, Influencer 1.06x; attribution over-claims 5.5x. Action: cut Influencer, test Meta/TikTok incrementality, speed up pages.",
        6: "Delays from Sewing/Finishing (68% of delay days) and LINE-04 (20% vs 15%); overtime >15h = 66% late. Action: rebalance stages, cap overtime.",
        7: "Cost of poor quality EGP 20.3M = 31% of GP; no dominant defect, 12% unclassified; fabric/stitching defects link to returns (r=0.33). Action: coding discipline, process control.",
        8: "PR-M03 rejects 3.0% vs 2.6%; PR-M02 loses 591h; 80% of downtime unplanned. Action: PR-M03 calibration, PR-M02 mechanical reliability, SMED.",
        9: "SUP04/SUP09 on-time 40%/35% vs 71% for the rest; thread, ink, rib cotton highest shortage risk. Action: SLA, dual-source, safety stock.",
        10: "One chain: two-speed demand, under-priced wholesale, imbalanced stock, internal bottlenecks, eroding suppliers. Quantified base value EGP 8.8M GP/yr, 82% from pricing.",
    }
    for _, row in cases.iterrows():
        with st.expander(f"Case {row.Card_No} - {row.Title}", expanded=row.Card_No == 1):
            st.markdown(f"**Business problem:** {row.Business_Problem}")
            st.markdown(f"**Deliverable:** {row.Expected_Deliverable}")
            callout("good", f"**Finding:** {answers[int(row.Card_No)]}")
    st.subheader("Integrated chain (month-over-month changes)")
    corr = R["chain_corr"]
    plot(px.imshow(corr.round(2), text_auto=True, color_continuous_scale="RdBu_r", zmin=-1, zmax=1, aspect="auto"), 560)
    st.dataframe(R["value_at_stake"][["Action", "Low", "Base", "High", "Assumption"]].style.format({"Low": "{:,.0f}", "Base": "{:,.0f}", "High": "{:,.0f}"}), width="stretch", hide_index=True)


def page_opportunity(d, R, s):
    st.header("Opportunity: Wholesale Discount Governance")
    w = R["wholesale"]
    dg = R["discount_diagnostic"]
    kpi_row([("Wholesale gross margin", fmt_pct(w.Gross_Profit_EGP.sum() / w.Net_Sales_EGP.sum()), None), ("Avg discount", fmt_pct(w.Discount_Pct.mean()), None), ("Loss-making invoices", f"{int(w.Is_Loss_Making.sum()):,}", None), ("Discount predictable? (R2)", f"{dg['model_r2']:.3f}", "no")])
    c1, c2 = st.columns(2)
    with c1:
        t = w.groupby(["Quantity", "Discount_Pct"]).size().unstack(fill_value=0)
        t = t.div(t.sum(axis=1), axis=0)
        t.columns = [f"{c:.0%}" for c in t.columns]
        plot(px.imshow(t, text_auto=".0%", color_continuous_scale="Plasma", aspect="auto", labels=dict(x="Discount", y="Order quantity"), title="Discount mix by order size: identical at every size"), 400)
    with c2:
        g = w.groupby("Discount_Pct").agg(Units=("Quantity", "mean"), GM=("Gross_Margin_Pct", "mean")).reset_index()
        f = go.Figure()
        f.add_bar(x=[f"{x:.0%}" for x in g.Discount_Pct], y=g.Units, name="Avg units per order", marker_color=GREY)
        f.add_scatter(x=[f"{x:.0%}" for x in g.Discount_Pct], y=g.GM, name="Gross margin", yaxis="y2", line=dict(color=AMBER, width=3))
        f.update_layout(yaxis2=dict(overlaying="y", side="right", tickformat=".0%"), title="Deeper discount: same order size, much lower margin")
        plot(f, 400)
    st.dataframe(R["price_response"].style.format({"Coefficient": "{:.5f}", "CI_Low": "{:.5f}", "CI_High": "{:.5f}", "p_value": "{:.3f}"}), width="stretch", hide_index=True)
    st.caption("Price-response tests: a deeper discount does not change order size or re-order timing.")

    st.subheader("Policy simulator")
    policy = st.selectbox("Policy", M.POLICIES, index=1)
    loss = st.slider("Volume lost on re-priced lines", 0, 40, 10, 5) / 100
    r = M.simulate_policy(w, policy, loss)
    kpi_row([("Lines re-priced", fmt_pct(r["Share_Lines_Repriced"]), None), ("Wholesale margin", fmt_pct(r["New_GM"]), f"{(r['New_GM'] - r['Old_GM']) * 100:+.1f} pts"), ("Gross profit uplift (3 yrs)", fmt_egp(r["GP_Uplift"]), None), ("Loss-making lines left", f"{r['Loss_Making_Lines_After']:,}", None)])
    st.caption(f"Break-even volume loss for this policy: {M.breakeven_volume_loss(w, policy):.0%} of units on re-priced lines.")
    pt = R["policy_table"]
    plot(px.bar(pt, x="Policy", y="GP_Uplift_per_Year", color=pt.Volume_Loss_On_Repriced.map("{:.0%}".format), barmode="group", title="Added gross profit per year by policy and volume-loss assumption", labels={"color": "Volume loss"}), 360)

    st.subheader("Deal-desk quote checker")
    uc = A.unit_costs(s)
    prods = d["products"]
    q1, q2, q3 = st.columns(3)
    pid = q1.selectbox("Product", prods.Product_ID, format_func=lambda x: f"{x} - {prods.set_index('Product_ID').Product_Name[x][:40]}")
    qty = q2.number_input("Quantity (units)", 12, 200, 36, 1)
    disc = q3.slider("Quoted discount", 0.0, 0.45, 0.35, 0.01)
    res = M.evaluate_quote(pid, int(qty), float(disc), prods, uc)
    (callout("good" if res["Status"] == "AUTO-APPROVE" else "bad" if "REJECT" in res["Status"] or "DIRECTOR" in res["Status"] else "warn", f"**{res['Status']}** | margin {res['Gross_Margin']:.1%} | tier cap {res['Tier_Cap']:.0%} | margin-floor cap {res['Margin_Floor_Cap']:.0%} | counter-offer {res['Counter_Offer_Discount']:.0%}"))
    st.write(f"Order gross profit as quoted: **EGP {res['Order_GP_EGP']:,.0f}** -> at counter-offer: **EGP {res['Order_GP_at_Counter_EGP']:,.0f}**")
    st.subheader("Where the leakage sits")
    c1, c2 = st.columns(2)
    c1.dataframe(R["leakage_product"], width="stretch", hide_index=True)
    c2.dataframe(R["leakage_customer"].head(10), width="stretch", hide_index=True)


# -------------------------------------------------------------------- main
def main() -> None:
    d, R = load_data(), load_results()
    s_all = d["sales"]

    # ---- sidebar: HVIA brand block
    st.sidebar.markdown(
        '<div class="hv-logo"><img src="data:image/png;base64,' + LOGO_B64 + '" alt="HVIA Data & AI Solutions"/></div>'
        '<div class="hv-badge">EXECUTIVE ANALYTICS</div><div class="hv-divider"></div>',
        unsafe_allow_html=True,
    )
    st.sidebar.title("EL SHARNOUBY GROUP")
    st.sidebar.caption("HVIA executive dashboard | data Oct-2023 .. Sep-2026")
    st.sidebar.markdown('<div class="hv-section-label">NAVIGATION</div>', unsafe_allow_html=True)
    page = st.sidebar.radio("Section", ["1. Executive Overview", "2. Sales & Customers", "3. Operations & Inventory", "4. Marketing", "5. Procurement & Suppliers", "6. Case Briefs", "7. Opportunity / AI Solution"])
    st.sidebar.markdown('<div class="hv-divider"></div><div class="hv-section-label">FILTERS</div>', unsafe_allow_html=True)
    channels = st.sidebar.multiselect("Channel filter (pages 1-2)", ["Wholesale", "Retail", "Online"], default=["Wholesale", "Retail", "Online"])
    fys = st.sidebar.multiselect("Fiscal year (pages 1-2)", sorted(s_all.Fiscal_Year.unique()), default=sorted(s_all.Fiscal_Year.unique()))
    st.sidebar.markdown(
        '<div class="hv-side-card"><b>HVIA CONTROL CENTER</b><span>EXECUTIVE ANALYTICS</span><em>Learn · Build · Grow · Belong</em></div>',
        unsafe_allow_html=True,
    )
    s = s_all[s_all.Channel.isin(channels) & s_all.Fiscal_Year.isin(fys)]

    # ---- main: branded hero banner
    st.markdown(
        '<div class="hv-hero"><div class="hv-eyebrow">EL SHARNOUBY GROUP &nbsp;|&nbsp; HVIA DATA &amp; AI SOLUTIONS</div>'
        '<div class="hv-title">Executive Analytics Command Center</div>'
        '<div class="hv-sub">Sales, operations, marketing and supply chain performance in one view.</div>'
        '<div class="hv-steps">SEE<i></i>DIAGNOSE<i></i>DECIDE<i></i>ACT</div></div>',
        unsafe_allow_html=True,
    )

    if s.empty:
        st.warning("No data for the selected filters.")
        return
    pages = {"1": page_overview, "2": page_sales_customers, "3": page_operations, "4": page_marketing, "5": page_procurement, "6": page_cases, "7": page_opportunity}
    pages[page[0]](d, R, s)


main()